#!/usr/bin/env python3
"""Independent LL(1) ground-truth computer. Reads the repo grammars read-only."""
import re, json, sys

def parse_grammar(text):
    # split on "X::=" boundaries
    text = text.strip()
    parts = re.split(r'\s*(?=[A-Za-z]::=)', text)
    rules = []          # list of (lhs, [alts]) in file order
    for p in parts:
        p = p.strip()
        if not p:
            continue
        lhs, rhs = p.split('::=', 1)
        lhs = lhs.strip()
        alts = [a.strip() for a in rhs.strip().split('|')]
        alts = [a for a in alts if a != '']
        rules.append((lhs, alts))
    return rules

def analyze(name, text):
    rules = parse_grammar(text)
    order = [lhs for lhs, _ in rules]
    NT = set(order)
    start = order[0]
    prods = [(lhs, a) for lhs, alts in rules for a in alts]
    terminals = set()
    right_parts = set()
    for lhs, a in prods:
        right_parts.add(a)
        for ch in a:
            if ch not in NT and ch != '@':
                terminals.add(ch)

    # nullable
    nullable = set()
    changed = True
    while changed:
        changed = False
        for lhs, a in prods:
            if lhs in nullable:
                continue
            if a == '@' or all(c in nullable for c in a):
                nullable.add(lhs); changed = True

    # FIRST of nonterminals (fixpoint)
    FIRST = {A: set() for A in NT}
    def first_str(s):
        out = set()
        if s == '@':
            return {'@'}
        for ch in s:
            if ch == '@':
                out.add('@'); continue
            if ch in NT:
                out |= (FIRST[ch] - {'@'})
                if ch not in nullable:
                    return out
            else:
                out.add(ch); return out
        out.add('@')
        return out
    changed = True
    while changed:
        changed = False
        for lhs, a in prods:
            n = len(FIRST[lhs]); FIRST[lhs] |= first_str(a)
            if len(FIRST[lhs]) != n: changed = True

    # FOLLOW (standard)
    FOLLOW = {A: set() for A in NT}
    FOLLOW[start].add('#')
    changed = True
    while changed:
        changed = False
        for lhs, a in prods:
            if a == '@': continue
            for i, ch in enumerate(a):
                if ch not in NT: continue
                rest = a[i+1:]
                f = first_str(rest) if rest else {'@'}
                add = f - {'@'}
                if '@' in f:
                    add |= FOLLOW[lhs]
                n = len(FOLLOW[ch]); FOLLOW[ch] |= add
                if len(FOLLOW[ch]) != n: changed = True
    FOLLOW_ALL = {A: (FOLLOW[A] | {'#'}) for A in NT}

    cols = sorted(terminals) + ['#']
    def build(follow):
        table = {A: {c: [] for c in cols} for A in order}
        for lhs, a in prods:
            f = first_str(a)
            for t in f - {'@'}:
                table[lhs][t].append(f"{lhs}::={a}")
            if '@' in f:
                for t in follow[lhs]:
                    table[lhs][t].append(f"{lhs}::={a}")
        return table
    t_std, t_all = build(FOLLOW), build(FOLLOW_ALL)
    def conflicts(t):
        return [(A, c, v) for A in order for c in cols
                if len(set(t[A][c])) > 1 for v in [sorted(set(t[A][c]))]]
    return dict(
        name=name, start=start, rule_order=order,
        nonterminals=sorted(NT), terminals=sorted(terminals),
        right_parts_sorted=sorted(right_parts),
        nullable=sorted(nullable),
        first_of_rhs={s: sorted(first_str(s)) for s in sorted(right_parts)},
        first_of_nt={A: sorted(FIRST[A]) for A in order},
        follow_std={A: sorted(FOLLOW[A]) for A in order},
        follow_alwayshash={A: sorted(FOLLOW_ALL[A]) for A in order},
        follow_diff={A: sorted(FOLLOW_ALL[A] - FOLLOW[A]) for A in order
                     if FOLLOW_ALL[A] != FOLLOW[A]},
        cols=cols,
        table_std={A: {c: (t_std[A][c][0] if t_std[A][c] else '') for c in cols} for A in order},
        table_alwayshash={A: {c: (t_all[A][c][0] if t_all[A][c] else '') for c in cols} for A in order},
        cells_added_by_alwayshash=[f"[{A}][{c}]={t_all[A][c][0]}" for A in order for c in cols
                                   if not t_std[A][c] and t_all[A][c]],
        conflicts_std=conflicts(t_std),
        conflicts_alwayshash=conflicts(t_all),
    )

out = []
for i in (1, 2, 3):
    p = f"/workspace/Parser/test{i}.txt"
    out.append(analyze(f"test{i}.txt", open(p).read()))
print(json.dumps(out, indent=1, ensure_ascii=False))

