def parse(G, s, key='table_std'):
    tbl=G[key]; start=G['rule_order'][0]; NT=set(G['rule_order'])
    st=['#',start]; inp=list(s)+['#']; i=0; steps=0
    while st:
        top=st[-1]; cur=inp[i]; steps+=1
        if steps>200: return 'LOOP'
        if top=='#':
            return 'ACCEPT' if cur=='#' else 'REJECT(stack empty, input left)'
        if top in NT:
            p=tbl[top].get(cur,'')
            if not p: return f'REJECT(no entry [{top}][{cur}])'
            st.pop(); body=p.split('::=')[1]
            if body!='@': st.extend(reversed(list(body)))
        else:
            if top==cur: st.pop(); i+=1
            else: return f'REJECT(mismatch {top} vs {cur})'
    return 'REJECT'

